const now = new Date();
const caracasOffset = -4 * 60;
const localNow = new Date(now.getTime() + (now.getTimezoneOffset() + caracasOffset) * 60000);

const pad = (n) => String(n).padStart(2, '0');
const todayStr = `${localNow.getFullYear()}-${pad(localNow.getMonth() + 1)}-${pad(localNow.getDate())}`;

const localPlus4 = new Date(localNow.getTime() + 4 * 24 * 60 * 60000);
const todayPlus4Str = `${localPlus4.getFullYear()}-${pad(localPlus4.getMonth() + 1)}-${pad(localPlus4.getDate())}`;

const getField = (obj, regex) => {
  if (!obj) return '';
  for (const k of Object.keys(obj)) {
    if (regex.test(k)) {
      const v = obj[k];
      if (v !== undefined && v !== null) return v;
    }
  }
  return '';
};

const normalizeDate = (val) => {
  if (!val) return '';
  const str = String(val).trim();
  const raw = str.split(' ')[0].split('T')[0];
  const p = raw.split(/[\/\-]/);
  if (p.length === 3) {
    if (p[0].length === 4) {
      return `${p[0]}-${pad(p[1])}-${pad(p[2])}`;
    } else if (p[2].length === 4 || p[2].length === 2) {
      const yr = p[2].length === 2 ? '20' + p[2] : p[2];
      let day = p[0];
      let month = p[1];
      if (parseInt(month, 10) > 12 && parseInt(day, 10) <= 12) {
        day = p[1];
        month = p[0];
      }
      return `${yr}-${pad(month)}-${pad(day)}`;
    }
  }
  return raw;
};

const formatSpanishDate = (isoStr) => {
  if (!isoStr) return '';
  const parts = String(isoStr).trim().split(' ')[0].split('T')[0].split(/[\/\-]/);
  const months = [
    'Enero', 'Febrero', 'Marzo', 'Abril', 'Mayo', 'Junio',
    'Julio', 'Agosto', 'Septiembre', 'Octubre', 'Noviembre', 'Diciembre'
  ];
  if (parts.length === 3) {
    if (parts[0].length === 4) {
      const day = parseInt(parts[2], 10);
      const monthIdx = parseInt(parts[1], 10) - 1;
      if (monthIdx >= 0 && monthIdx < 12 && !isNaN(day)) {
        return `${day} de ${months[monthIdx]}`;
      }
    } else {
      let day = parseInt(parts[0], 10);
      let monthIdx = parseInt(parts[1], 10) - 1;
      if (monthIdx >= 12 && day <= 12) {
        monthIdx = parseInt(parts[0], 10) - 1;
        day = parseInt(parts[1], 10);
      }
      if (monthIdx >= 0 && monthIdx < 12 && !isNaN(day)) {
        return `${day} de ${months[monthIdx]}`;
      }
    }
  }
  return isoStr;
};

